package com.nkwabyte.cropdiseasedetection.common.data

/**
 * Hausa (ha) body text, keyed by [DiseaseInfo.id].
 *
 * See [DiseaseTranslations] for the overlay contract. Ids absent from this map
 * fall back to English, so this file may be filled a few diseases at a time.
 *
 * The Twi vernacular name in `localName` is kept — it is the name a Ghanaian
 * farmer hears in the field — and only its gloss is translated.
 *
 * Product names, active ingredients, doses, concentrations and growth stages
 * are kept verbatim, as they appear on the label.
 *
 * Pending native-speaker review.
 */
object HausaDiseaseText {
    val entries: Map<Int, DiseaseTranslation> = mapOf(

        // ── MASARA ────────────────────────────────────────────────────────────

        0 to DiseaseTranslation(
            localName = "Aburo Nhwiren Tuntum (cutar tabon toka ta masara)",
            description = "Ana kuma kiranta cutar tabon toka. Wannan cuta ta naman gwari tana daga cikin cututtukan masara mafi yin barna a duniya. Tana bunƙasa a lokacin zafi da danshi, kuma tana iya haifar da babbar asara idan ta kama tun farkon kakar noma.",
            symptoms = "Ƙananan tabo masu siffar murabba'i, launin ruwan kasa zuwa toka, suna bin jijiyoyin ganye. Da lokaci tabon yana faɗaɗa ya zama dogayen layuka na toka da suke haɗuwa su lalata babban sashe na ganye. Gonakin da suka kamu sosai suna kama da waɗanda wuta ta ci.",
            causes = "Naman gwari mai suna Cercospora zeae-maydis, wanda yake rayuwa a cikin sharar masara da ta rage a saman ƙasa. Ana sakin ƙwayoyinsa a lokacin zafi da danshi, iska da tsatsan ruwan sama kuma suna yaɗa su.",
            effects = "Yana rage sashen ganye da yake yin abinci, wanda yake haifar da asarar amfani kashi 10 zuwa 50. Kamuwa mai tsanani yana raunana kara, saboda haka tsire-tsire suna faɗuwa kafin girbi. Ingancin hatsi ma yana raguwa a gonakin da suka kamu sosai.",
            prevention = "Yi amfani da iri mai inganci wanda yake jure cutar. Yi juyin shuka — kada ka shuka masara bayan masara. Binne sharar da ta kamu ta hanyar noma ƙasa. Bar isasshen sarari tsakanin tsire-tsire domin iska ta shiga. Duba gona akai-akai daga tsakiyar kaka.",
            organicMitigation = "• Sa maganin naman gwari na Trichoderma (Trichoderma harzianum) a ƙasa da kuma a fesa a kan ganye.\n• Fesa maganin man neem (Azadirachta indica) duk mako 3 zuwa 4.\n• Fesa ruwan taki (compost tea) a kan ganye domin ƙarfafa garkuwar tsiro.\n• Cire ka ƙone ganyen da suka kamu sosai da sauran sharar bayan girbi.\n• Haɗa shuka da wake domin karya zagayowar cutar da inganta ƙasa.",
            chemicalMitigation = "• Azoxystrobin (Quadris): Sa daga matakin VT (fitowar fure) zuwa R1 (fitowar gemu). Maimaita bayan kwana 14 idan an buƙata.\n• Pyraclostrobin + Boscalid (Pristine): Yana da tasiri sosai; sa shi kafin cutar ta kama.\n• Propiconazole (Tilt): Sa da zarar ka ga alamar cutar; bi ma'aunin da yake kan lambar kwalba.\n• Trifloxystrobin: Ana iya haɗa shi da propiconazole a cikin tanki domin ƙarin tasiri.\n• Koyaushe ka canza nau'in maganin naman gwari domin kada cutar ta saba da shi."
        ),

        1 to DiseaseTranslation(
            localName = "Aburo Nhwiren Atoro (tsatsa ta masara)",
            description = "Cutar tsatsa ce ta naman gwari wadda take yaɗuwa da sauri a lokacin sanyi da danshi. Ana ganin ƙuraje masu launin ja kamar tubali a bangarorin ganye biyu. Ta yaɗu a Yammacin Afirka har da Ghana, musamman a safiya mai sanyi da danshi.",
            symptoms = "Ƙuraje masu ƙura, launin ruwan kasa zuwa ja kamar tubali, a saman da ƙarƙashin ganye. Daga baya a kakar suna juyawa baƙi. Ganyen da ya kamu sosai yana yin rawaya ya mutu kafin lokacinsa.",
            causes = "Naman gwari mai suna Puccinia sorghi. Iska tana kawo ƙwayoyinsa daga yankunan kudu. Sanyi (16 zuwa 23 °C) da dogon lokacin raɓa (fiye da awa 6 na danshi a ganye) suna taimaka wa kamuwa.",
            effects = "Yana rage yin abinci na tsiro, wanda yake haifar da asara kashi 5 zuwa 40 gwargwadon lokacin da cutar ta kama. Kamuwa da wuri kafin fitowar fure shi ne mafi yin barna. Tsire-tsire da suka kamu sosai suna ba da hatsi mai nauyi kaɗan da rashin cikawa.",
            prevention = "Shuka iri masu jure tsatsa — wannan ita ce hanya mafi inganci na dogon lokaci. Shuka da wuri yana rage haɗuwa da lokacin da ƙwayoyin cutar suka yi yawa. Lalata masarar da ta tsiro da kanta da sauran tsire-tsire masu ɗauke da cutar. Duba gona kowane mako daga matakin V8.",
            organicMitigation = "• Shuka nau'in masara masu jure cutar (ka tambayi masu sayar da iri a yankinka).\n• Lalata sharar da ta kamu da masarar da ta tsiro da kanta bayan girbi.\n• Fesa man neem (maganin kashi 2 zuwa 3) da zarar ka ga alamar cutar.\n• Ƙurar sulfur ko sulfur mai narkewa yana iya hana kamuwa da wuri.\n• Tabbatar da isasshen potassium a ƙasa — tsire-tsire da suka rasa shi suna kamuwa da sauri.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Maganin kariya; sa da zarar ƙuraje na farko sun fito.\n• Propiconazole (Tilt 250 EC): Yana shiga cikin tsiro; sa kafin matakin VT domin sakamako mafi kyau.\n• Tebuconazole (Folicur): Yana da tasiri; sa idan cutar ta kai kashi 5 na gona.\n• Azoxystrobin: Yana yin kariya da kuma magani.\n• Sa maganin kafin fitowar gemu idan tsatsa tana nan — sa bayan haka ba shi da riba sosai."
        ),

        2 to DiseaseTranslation(
            localName = "Aburo Pa (masara mai lafiya)",
            description = "Wannan tsiron masara ba shi da wata alamar cuta, ko lalacewar ƙwari, ko rashin abinci. Masara mai lafiya tana da ganye kore mai haske da ƙarfi, kuma tana kan hanyar ba da amfani mai kyau.",
            symptoms = "Ganye kore iri ɗaya mai haske, babu tabo ruwan kasa, babu layuka, babu rawaya, babu yaushewa. Kara mai ƙarfi da tsayi, fure da ya fito sosai, da kwaya masu girma iri ɗaya da gemu mai kyau.",
            causes = "Ƙasa mai wadataccen abinci, ruwan sama ko ban ruwa akai-akai, iri mai inganci, adadin tsire-tsire da ya dace, da kyakkyawan tafiyar da gona gaba ɗaya.",
            effects = "Amfani mai yawa, hatsi mai nauyi, kara mai ƙarfi da ba ya faɗuwa. Tsiron zai iya ba da cikakken amfaninsa tare da asara kaɗan bayan girbi.",
            prevention = "Ci gaba da yadda kake tafiyar da gonar. Yi zagayen gona akai-akai (aƙalla sau ɗaya a mako) domin ganin alamar cuta ko ƙwari kafin ta yi girma. Ajiye rikodin abin da ka sa domin taimaka maka a nan gaba.",
            organicMitigation = "• Ci gaba da sa taki na ganye da sauran kayan halitta domin kula da rayuwar ƙasa.\n• Yi juyin shuka da wake (wake, soya) domin ƙara nitrogen a ƙasa ta dabi'a.\n• Yi shuka haɗe-haɗe domin cin gajiyar gona da hana ciyawa.\n• Ci gaba da fesa ƙananan abinci a kan ganye idan kana yi.\n• Gina hanyoyin adana ruwa (kunyoyi, rufe ƙasa da ciyawa) domin riƙe danshi.",
            chemicalMitigation = "• Sa taki NPK mai daidaito (misali 15-15-15 ko 23-10-5) bisa ma'aunin da aka ba da shawara.\n• Sa urea (46-0-0) a gefen tsiro a matakin gwiwa (V6) domin ƙarin nitrogen.\n• Fara shirin maganin naman gwari na kariya a lokacin fitowar fure idan kakar da ta wuce tana da cuta.\n• Kada ka sa maganin ƙwari na tsutsar kara sai idan lalacewar ta kai kashi 10.\n• Bi jadawalin fesawa da CABI ko MoFA (Ma'aikatar Abinci da Noma ta Ghana) suka ba da shawara."
        ),

        3 to DiseaseTranslation(
            localName = "Aburo Nhwiren Ohow (cutar ƙona ganyen masara)",
            description = "Cuta ce ta naman gwari mai yin barna, tana rage sashen ganye da sauri kuma tana rage yin abinci na tsiro. Manyan tabo masu siffar taba, launin ruwan kasa, su ne alamarta ta musamman. Tana da tsanani a wuraren da zafi ba shi da yawa kuma raɓa take daɗewa, kamar yankunan gandun daji na Ghana.",
            symptoms = "Manyan tabo masu tsawo kamar taba (santimita 3 zuwa 15), launin toka-kore zuwa ruwan kasa, suna bin jijiyoyin ganye. Suna farawa daga ganyen ƙasa suna hawa sama. Sashen da ya kamu yana juyawa ruwan kasa ko toka, kuma yana iya yin baƙi lokacin da naman gwari yake fitar da ƙwayoyinsa.",
            causes = "Naman gwari Exserohilum turcicum (a dā ana kiransa Helminthosporium turcicum). Yana rayuwa a cikin sharar masara. Zafi matsakaici (18 zuwa 27 °C) da dogon danshi a ganye (fiye da awa 6) suna taimaka masa. Iska da tsatsan ruwan sama suna yaɗa ƙwayoyinsa.",
            effects = "Yana iya haifar da asara kashi 30 zuwa 50 idan ya kama kafin ko lokacin fitowar fure. Faɗuwar ganye mai yawa tana rage cikawar kwaya da nauyin hatsi. Kamuwa mai tsanani da wuri yana iya sa a rasa amfani gaba ɗaya a nau'in da ba ya jure cutar.",
            prevention = "Shuka iri masu jure cutar — wannan ita ce hanya mafi muhimmanci. Yi juyin shuka da tsire-tsire da ba na gadar ciyawa ba (wake, kayan lambu). Binne sharar da ta kamu bayan girbi domin rage ƙwayoyin cutar. Kada ka sa nitrogen da yawa, domin yana sa ganye ya yi laushi ya kamu da sauri.",
            organicMitigation = "• Yi amfani da nau'in masara masu jure cutar (nemi nau'in da CSIR-SARI ko IITA suka ba da shawara a Ghana).\n• Sa Trichoderma harzianum a ƙasa da kuma a fesa a kan ganye.\n• Sa gyaɗar neem a ƙasa domin rage ƙwayoyin cutar da ke cikinta.\n• Cire ka lalata sharar tsire-tsire da ta kamu bayan girbi — kada ka bar ta a gona.\n• Haɗa shuka da wake domin karya zagayowar cutar.",
            chemicalMitigation = "• Propiconazole (Tilt 250 EC): Sa a matakin V8 zuwa V10 kafin fitowar fure; maimaita duk kwana 14.\n• Azoxystrobin: Yana da tasiri sosai a matsayin kariya; sa da zarar ka ga alamar cutar.\n• Pyraclostrobin + Metconazole (Headline AMP): Yana magance cututtuka da yawa; yana da kyau sosai ga wannan cuta.\n• Mancozeb: Maganin kariya; sa shi kafin cutar ta kama lokacin da yanayi ya dace da ita.\n• Sa maganin kafin fitowar gemu shi ne mafi riba."
        ),

        4 to DiseaseTranslation(
            localName = "Aburo Nhwiren Mfirimiri (cutar layukan masara)",
            description = "Cutar layukan masara ita ce cutar ƙwayar cuta ta masara mafi yin barna a Afirka. Ƙwayar cuta ta Maize Streak Virus (MSV) ce take haifar da ita, kuma ƙwaron leafhopper yake ɗauka. Tana ko'ina a Afirka ta Kudu da Sahara har da Ghana. Nau'in da ba ya jure ta yana iya rasa amfani kusan gaba ɗaya.",
            symptoms = "Ƙunƙuntattun layuka masu yankewa, launin fari-rawaya, suna bayyana a jikin jijiyoyin ganye, suna yin zane mai layukan kore-rawaya. Tsire-tsire da suka kamu sosai suna yin gajarta da kwaya ƙanana ko marasa kyau. A matakin ƙarshe ganye na iya yin fari ya koma rawaya gaba ɗaya.",
            causes = "Maize Streak Virus (MSV), wata ƙwayar cuta ta Geminivirus da ƙwaron leafhopper (Cicadulina spp.) yake ɗauka. Ƙwayar cutar ba ta yaɗuwa ta ƙasa ko ta taɓawa — sai da ƙwaron. Ƙwaron yana yawaita a lokacin zafi da bushewa.",
            effects = "Asara kashi 30 zuwa 100 gwargwadon nau'in da shekarun tsiron lokacin da ya kamu. Kamuwa da wuri (cikin mako biyu bayan tsirowa) yana sa a rasa amfani kusan gaba ɗaya. Tsire-tsire masu gajarta ba sa ba da hatsi mai amfani. Wannan babbar matsala ce ga ƙananan manoma a Ghana.",
            prevention = "Hanya mafi inganci ita ce shuka nau'in da yake jure MSV — waɗanda suke da kwayar halittar juriya (misali STRIGA 6, STRIGA 4, ko nau'in da IITA ta fitar). Shuka da wuri yana rage haɗuwa da lokacin da ƙwaron ya yi yawa. Cire ciyawa a gefen gona, domin ita ce mafakar ƙwaron.",
            organicMitigation = "• Shuka nau'in da aka tabbatar yana jure MSV (ana ba da shawara sosai).\n• Shuka da wuri (farkon ruwan sama): tsire-tsire su girma kafin ƙwaron ya yawaita.\n• Haɗa masara da wake ko rogo domin dakatar da motsin ƙwaron.\n• Cire tsire-tsire da suka kamu sosai da wuri domin rage mafakar ƙwayar cutar.\n• Kiyaye gefen gona daga ciyawar gadar da take ɗauke da ƙwaron.\n• Tarkon rawaya mai manne yana taimakawa wajen sanin adadin ƙwaron.",
            chemicalMitigation = "• Maganin iri na Imidacloprid (Gaucho 600 FS): Yana da tasiri sosai wajen kare ƙananan tsire-tsire daga cizon ƙwaron a cikin makonni 3 na farko masu muhimmanci.\n• Maganin iri na Thiamethoxam (Cruiser): Madadin Imidacloprid domin kariya da wuri.\n• Maganin ƙwari na fesawa (Dimethoate, Chlorpyrifos): Sa domin magance ƙwaron idan ba a yi wa iri magani ba; sa da zarar ka ga ƙwaron.\n• Lura: Maganin ƙwari yana kashe ƙwaron amma ba ya warkar da tsiron da ya kamu. Ka mai da hankali kan riga-kafi."
        ),

        // ── BARKONO ───────────────────────────────────────────────────────────

        5 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko (tabon ƙwayoyin cuta na barkono)",
            description = "Cuta ce ta ƙwayoyin cuta mai yin barna, tana kama ganye, kara da 'ya'yan barkono a lokacin zafi da danshi. Ta yaɗu a yankunan noma masu danshi na Ghana. Faɗuwar ganye da wuri da tabo a kan 'ya'ya suna haifar da babbar asara, musamman ga barkono na fitarwa waje.",
            symptoms = "Ƙananan tabo masu zagaye, duhu kuma kamar an jiƙa su, a kan ganye (milimita 2 zuwa 10), suna juyawa ruwan kasa da da'ira rawaya kewaye da su. Tabon na iya haɗuwa ya zama manyan wurare da suka mutu. Rawaya da faɗuwar ganye suna bar 'ya'ya a fili ga rana. 'Ya'yan suna yin tabo duhu masu tashi kamar ƙaiƙayi, wanda yake rage darajarsu a kasuwa.",
            causes = "Ƙwayar cuta Xanthomonas campestris pv. vesicatoria (da kuma X. perforans da X. euvesicatoria). Tana yaɗuwa ta tsatsan ruwan sama, ban ruwa daga sama, kayan aiki masu ɗauke da ita, iri da suka kamu, da kuma tsire-tsire da aka dasa. Zafi (25 zuwa 30 °C) da danshi a ganye suna taimaka mata.",
            effects = "Faɗuwar ganye mai tsanani tana raunana tsiro tana kuma bar 'ya'ya a fili ga rana da sauran cututtuka. Tabo a kan 'ya'ya yana rage darajarsu kashi 40 zuwa 60. Asarar amfani na iya kai kashi 50 a lokacin damina. Ana ƙin barkono na fitarwa waje saboda tabon.",
            prevention = "Yi amfani da iri da tsire-tsire da aka tabbatar ba su da cuta, daga wurin amintattun masu sayarwa. Kada ka yi ban ruwa daga sama — yi amfani da ban ruwa na ɗigo ko na kwarara. Rage tafiya a gona lokacin da take da danshi. Wanke kayan datse tsakanin tsire-tsire. Yi juyin shuka na shekara 2 zuwa 3 da amfanin gona da ba na barkono ba.",
            organicMitigation = "• Yi amfani da maganin tagulla na halitta (Bordeaux mixture: kashi 1 na copper sulfate + lemun ƙasa) a matsayin kariya duk kwana 7 zuwa 10.\n• Fesa man neem (kashi 2) da sabulun castile (kashi 0.5) domin rage ƙwayoyin cuta da ƙarfafa garkuwar tsiro.\n• Cire ka lalata ganyen da suka kamu da sharar tsire-tsire.\n• Rufe ƙasa a gindin tsiro domin hana tsatsan ƙasa ya kai ga ganyen ƙasa.\n• Sa taki na ganye domin inganta rayuwar ƙasa da ƙarfin tsiro.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000): Shi ne aka fi amfani da shi; sa duk kwana 7 a lokacin danshi.\n• Copper oxychloride + Mancozeb (Cuprosan): Haɗi mai tasiri ga ƙwayoyin cuta da naman gwari.\n• Streptomycin sulfate (inda doka ta yarda): Sa a farkon kamuwa, ka canza tsakaninsa da tagulla.\n• Acibenzolar-S-methyl (Actigard): Yana tayar da garkuwar tsiro — a yi amfani da shi tare da tagulla.\n• Kada ka sa tagulla a lokacin zafi da rana mai ƙarfi domin gudun cutar da tsiron."
        ),

        6 to DiseaseTranslation(
            localName = "Mako Nhwiren Akyekyere (cutar idon kwaɗo ta barkono)",
            description = "Ana kuma kiranta cutar idon kwaɗo. Wannan kamuwa da naman gwari yana haifar da tabo masu zagaye da tsakiya mai haske da baki mai duhu, kamar idon kwaɗo. Ta zama ruwan dare a Ghana a lokacin danshi da ruwan sama. Kamuwa akai-akai a cikin kaka yana haifar da faɗuwar ganye a hankali.",
            symptoms = "Tabo masu zagaye (milimita 5 zuwa 15) da tsakiya launin ruwan kasa zuwa toka da baki ruwan kasa mai duhu zuwa shuɗi. Tsakiyar na iya faɗuwa ya bar rami. Ganye yana yin rawaya kewaye da tabon ya faɗi. Kamuwa mai yawa yana sa ganye ya faɗi gaba ɗaya.",
            causes = "Naman gwari Cercospora capsici. Yana rayuwa a cikin sharar tsire-tsire da ta kamu. Ana samar da ƙwayoyinsa a lokacin zafi (25 zuwa 30 °C), danshi da ruwan sama. Ana kuma yaɗa shi ta iri da suka kamu.",
            effects = "Faɗuwar ganye a hankali tana rage yin abinci na tsiro tana kuma bar 'ya'ya a fili ga rana. Asara kashi 20 zuwa 40 ta zama ruwan dare a gonar da ba a kula da ita. Faɗuwar ganye akai-akai tana raunana tsiro ta sa ya kamu da sauran cututtuka.",
            prevention = "Shuka daga iri masu inganci marasa cuta. Bar isasshen sarari (santimita 60 tsakanin tsire-tsire) domin iska ta shiga. Cire sharar da ta kamu da sauri. Yi juyin shuka na aƙalla shekara 2 da amfanin gona da ba na barkono ba.",
            organicMitigation = "• Fesa maganin copper sulfate (Bordeaux mixture) a matsayin kariya duk kwana 10 zuwa 14.\n• Fesa haɗin man neem da bicarbonate (cokali ƙarami 1 na baking soda + cokali babba 1 na man neem a kowace lita).\n• Cire ka lalata dukan ganye da sharar da suka kamu.\n• Sa Trichoderma harzianum a matsayin ruwan ƙasa domin rage ƙwayoyin cutar da ke ƙasa.\n• Sarari mai kyau da datsewa suna inganta shigar iska su rage danshi kewaye da tsiro.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Maganin kariya; sa duk kwana 7 zuwa 10 a lokacin danshi.\n• Chlorothalonil (Bravo 500): Maganin kariya mai tasiri sosai; sa duk kwana 7 zuwa 14.\n• Azoxystrobin (Amistar): Yana shiga cikin tsiro; sa da zarar ka ga alamar cutar.\n• Difenoconazole (Score 250 EC): Yana shiga cikin tsiro; sa duk kwana 14 domin warkarwa.\n• Canza nau'in maganin duk sa 2 zuwa 3 domin kada cutar ta saba da shi."
        ),

        7 to DiseaseTranslation(
            localName = "Mako Nhwiren Ohow (cutar ƙona ganyen barkono)",
            description = "Kamuwa da naman gwari wanda yake fara kama tsofaffin ganye na ƙasa, yana yin tabo masu da'ira kamar abin harbi. Ta zama ruwan dare a yankunan noman barkono na Ghana, musamman a damina lokacin da zafi da danshi suke daɗewa.",
            symptoms = "Tabo ruwan kasa zuwa baƙi (milimita 10 zuwa 15) masu da'ira suna ba da kamannin abin harbi, da farko a tsofaffin ganye na ƙasa. Da'ira rawaya na iya kewaye tabon. Tabon yana sa ganye ya yi rawaya ya faɗi. A yanayi mai tsanani faɗuwar ganye tana hawa sama da sauri.",
            causes = "Naman gwari Alternaria capsici ko A. alternata. Suna zaune a ƙasa da kuma a iri. Suna rayuwa a cikin sharar da ta kamu. Zafi (24 zuwa 29 °C), danshi mai yawa, da sauyawa tsakanin jiƙa da bushewa suna taimaka musu.",
            effects = "Faɗuwar ganye tana farawa daga gindin tsiro tana hawa sama, tana rage yin abinci sosai. 'Ya'yan da suka bayyana suna ƙonewa da rana kuma suna ruɓewa. Ba tare da magani ba, asara na iya kai kashi 30 zuwa 50 a gonar da ta kamu sosai.",
            prevention = "Ba da ruwa a gindin tsiro kaɗai — kada ka jiƙa ganye. Yi juyin shuka na aƙalla shekara 2 da tsire-tsire da ba na barkono ba. Yi wa tsiro sanda domin ganye kada ya taɓa ƙasa. Cire ganyen ƙasa da suke taɓa ƙasa. Kada ka sa nitrogen da yawa, domin yana sa tsiro ya yi laushi ya kamu.",
            organicMitigation = "• Rufe gindin tsiro da taki na ganye (kauri santimita 5) domin hana tsatsan ƙasa ya kai ga ganye.\n• Fesa copper sulfate (Bordeaux mixture) a matsayin kariya.\n• Fesa man neem (kashi 2 zuwa 3) domin hana naman gwari girma.\n• Fesa haɗin bicarbonate da man neem a kan ganye domin canza yanayin saman ganye ya hana naman gwari.\n• Cire ka lalata ganyen ƙasa da suka kamu da zarar ka gan su.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500): Sa duk kwana 7 zuwa 10 a matsayin kariya a lokacin danshi.\n• Iprodione (Rovral): Maganin warkarwa ga Alternaria; sa a farkon kamuwa.\n• Azoxystrobin (Amistar): Yana shiga cikin tsiro; sa a matsayin kariya lokacin dasawa sannan duk kwana 14.\n• Boscalid + Pyraclostrobin (Bellis): Haɗi mai inganci wanda yake da tasiri kan Alternaria.\n• Copper oxychloride: Sa a matsayin kariya duk kwana 10 a lokacin damina."
        ),

        8 to DiseaseTranslation(
            localName = "Mako Kobuo (cutar yaushewar barkono)",
            description = "Cuta ce ta naman gwari da ke zaune a ƙasa, tana yin barna sosai. Tana shiga hanyoyin ruwa na tsiron barkono, tana haifar da yaushewa a hankali har tsiron ya mutu. Idan ta shiga gona, tana zama a ƙasa shekaru masu yawa. Ta zama ruwan dare a noman barkono na ban ruwa a Ghana.",
            symptoms = "Rawaya na ganyen ƙasa yana hawa sama. Yaushewar rassa a lokacin zafi na rana wanda ba ya warkewa da ban ruwa. Tsire-tsire suna faɗuwa su mutu daga ƙarshe. Canjin launi a ciki kara — ana ganin layuka ruwan kasa zuwa ja idan aka yanke kara kusa da gindi.",
            causes = "Naman gwari Fusarium oxysporum f.sp. capsici da ke zaune a ƙasa. Yana shiga ta saiwoyi ta wurin rauni ko ramuka na halitta. Yana rayuwa a ƙasa fiye da shekara 20 a matsayin chlamydospores. Ƙasa mai zafi (25 zuwa 30 °C), danshi mai yawa bayan fari, da ƙasa mai tsami suna taimaka masa.",
            effects = "Mutuwar tsiro cikin kwanaki zuwa makonni bayan kamuwa. Ana iya rasa amfani gaba ɗaya idan gona ta kamu duka. Ƙasa tana ci gaba da ɗauke da cutar shekaru masu yawa — barkono da za a shuka a wurin nan gaba zai sha wahala. Babu warkarwa idan tsiro ya kamu.",
            prevention = "Kada ka sake shuka barkono a gonar da ta taɓa kamuwa da wannan cuta har tsawon shekara 5. Ka kiyaye pH na ƙasa ya wuce 6.5 ta hanyar sa lemun ƙasa. Inganta fitar ruwa daga ƙasa — kada ruwa ya tsaya. Wanke kayan dasawa. Ka ɗauko tsire-tsire daga gonakin gandu masu inganci kaɗai.",
            organicMitigation = "• Ƙona ƙasa da rana: Rufe ƙasa mai danshi da leda mai haske na mako 4 zuwa 6 a lokacin zafi domin rage ƙwayoyin cutar da ke ƙasa sosai.\n• Sa Trichoderma harzianum a ƙasa (a matsayin ruwa ko a haɗa a ramin dasawa): yana zama a saiwoyi ya hana Fusarium.\n• Sa naman gwari mai amfani (Glomus spp.) a lokacin dasawa domin ƙarfafa saiwoyi.\n• Sa gyaɗar neem a ƙasa — tana da ikon kashe Fusarium.\n• Yi amfani da nau'in da suke jure cutar inda akwai su.",
            chemicalMitigation = "• Metalaxyl (Ridomil): Zuba a ƙasa lokacin dasawa a matsayin kariya; ba ya warkar da tsiron da ya kamu.\n• Carbendazim (Bavistin): Zuba a ƙasa ko yi wa iri magani; a yi amfani da shi a matsayin kariya kaɗai.\n• Maganin iri na Thiram: Yana kare saiwoyin ƙananan tsire-tsire lokacin girma.\n• Fludioxonil: Maganin iri mai tasiri kan ruɓewar gindi da Fusarium yake haifarwa.\n• Muhimmi: Babu maganin da yake warkar da cutar idan ta riga ta shiga — riga-kafi ita ce mabuɗi."
        ),

        9 to DiseaseTranslation(
            localName = "Mako Pa (barkono mai lafiya)",
            description = "Wannan tsiron barkono yana da cikakkiyar lafiya: ganye kore mai duhu, kara mai ƙarfi, da 'ya'ya masu girma sosai. Barkono mai lafiya yana nuna cewa ana bin kyawawan hanyoyin noma kuma amfanin gona zai yi kyau.",
            symptoms = "Ganye kore mai duhu mai haske, gefensa lallausa, babu tabo ko rawaya. Kara mai ƙarfi da tsayi. Furanni masu yawa, fari ko shuɗi. Barkono mai ƙarfi da haske, mai girman da ya dace kuma babu aibu.",
            causes = "Ƙasa mai kyau (pH 6.0 zuwa 6.8), kula da danshi akai-akai, isasshen sarari, abinci mai daidaito (NPK da ƙananan abinci), da kyakkyawan magance ƙwari da ciyawa.",
            effects = "Amfani mai yawa na barkono mai kyau a kasuwa. Tsire-tsire masu ƙarfi suna jure fari da cututtuka. Samarwa akai-akai yana taimaka wa kuɗin manomi da abincin gida.",
            prevention = "Kiyaye danshin ƙasa akai-akai ta ban ruwa na ɗigo ko shayarwa akai-akai. Rufe ƙasa domin riƙe danshi da hana ciyawa. Duba akai-akai domin ganin alamun ƙwari da cututtuka da wuri. Ajiye rikodin gona domin bin abin da ka sa da amfanin da ka samu.",
            organicMitigation = "• Sa taki na ganye da ya ruɓe sosai (kilo 2 zuwa 3 ga kowane tsiro) lokacin dasawa da kuma daga baya.\n• Rufe ƙasa da ciyawa ko busasshiyar ciyawa (santimita 8 zuwa 10) domin riƙe danshi da hana ciyawa.\n• Shuka basil ko marigold kusa da barkono domin korar ƙwari da farin ƙwaro ta dabi'a.\n• Fesa man neem a matsayin kariya duk mako 2 zuwa 3 domin korar ƙwari da magance ƙananan cututtukan naman gwari.\n• Fesa ruwan kifi ko ruwan tsire-tsire da aka bar su su yi tsami a kan ganye domin ƙara ƙarfin tsiro.",
            chemicalMitigation = "• Sa taki NPK mai daidaito (misali 12-12-17 a lokacin 'ya'ya).\n• Ƙara calcium nitrate domin hana ruɓewar gindin 'ya'ya.\n• Sa magnesium sulfate (fesa Epsom salt a kan ganye) idan ka ga rawaya tsakanin jijiyoyi.\n• Fesa tagulla a matsayin kariya a farkon damina.\n• Yi wa iri maganin ƙwari a matakin gandu domin kare ƙananan tsire-tsire."
        ),

        10 to DiseaseTranslation(
            localName = "Mako Nhwiren Kwanee (cutar mutuwar ganyen barkono)",
            description = "Cuta ce mai yin barna sosai wadda Phytophthora infestans yake haifarwa (irin cutar da ta haifar da yunwar dankalin Ireland). Tana iya lalata gonar barkono duka cikin kwanaki a lokacin sanyi da danshi. Saurin yaɗuwarta ya sa ta zama daga cikin cututtukan da aka fi ji tsoro a duniya.",
            symptoms = "Tabo masu duhu kamar an shafa musu mai kuma kamar an jiƙa su, a ganye da kara, suna faɗaɗa da sauri. Farin fulawa kamar auduga a ƙarƙashin ganye a lokacin danshi. Kara yana yin tabo ruwan kasa mai duhu kuma yana iya faɗuwa. 'Ya'ya suna yin tabo ruwan kasa mai duhu masu ƙarfi.",
            causes = "Phytophthora infestans (ba naman gwari na gaskiya ba ne). Yana yaɗuwa ta iska a lokacin sanyi (15 zuwa 20 °C) da danshi. Yana iya tafiya kilomita da yawa da iska. Yana bunƙasa a dare mai sanyi da raɓar safiya.",
            effects = "Ana iya lalata gona duka cikin kwana 3 zuwa 7 idan yanayi ya dace. Kamuwar 'ya'ya tana sa ba a iya sayar da su. Babbar asara musamman a lokacin ruwan sama na ƙarshen kaka a Ghana.",
            prevention = "Kada ka shuka da kusanci — bar iska ta shiga. Kada ka yi ban ruwa daga sama. Bi hasashen yanayi a lokacin sanyi da ruwan sama ka sa magani kafin cutar ta kama. Cire ka ƙone duk tsiron da ya kamu nan take. Kada ka bar sharar da ta kamu a gona.",
            organicMitigation = "• Bordeaux mixture (copper sulfate kashi 1 + lemun ƙasa): Sa duk kwana 5 zuwa 7 a lokacin sanyi da danshi a matsayin kariya mai ƙarfi.\n• Cire ka lalata dukan tsire-tsire da ganyen da suka kamu nan take — sa a jaka ka ƙone; kada ka mai da su taki.\n• Inganta fitar ruwa daga gona domin ruwa kada ya tsaya.\n• Kada ka shuka a wuraren kwari inda iska mai sanyi take taruwa.\n• Yi amfani da sabulun tagulla (copper octanoate) a matsayin madadin da aka yarda da shi ga noma na halitta.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ): Mafi tasiri; sa a matsayin kariya duk kwana 7 zuwa 10 a lokacin sanyi da danshi.\n• Cymoxanil + Mancozeb (Curzate M): Yana kariya kuma yana warkarwa; sa duk kwana 5 zuwa 7.\n• Dimethomorph (Forum): Yana shiga cikin tsiro; yana da tasiri kan Phytophthora; ka canza tsakaninsa da Ridomil.\n• Fosetyl-aluminum (Aliette): Yana shiga cikin tsiro ta saiwoyi da ganye; sa a matsayin kariya.\n• Canza nau'in maganin duk sa 2 zuwa 3 domin kada cutar ta saba da shi."
        ),

        11 to DiseaseTranslation(
            localName = "Mako Nhwiren Opapaee (cutar ruɓewar ganyen barkono)",
            description = "Suna ne na gaba ɗaya ga mutuwar ganye da sauri wadda naman gwari ko ƙwayoyin cuta suke haifarwa a barkono. Tana da manyan tabo masu duhu marasa siffa da suke faɗaɗa da sauri, wanda yake sa ganye ya mutu kuma tsiro ya raunana.",
            symptoms = "Manyan tabo ruwan kasa mai duhu ko kamar an jiƙa su, marasa siffa, suna farawa daga gefen ganye ko kansa. Mutuwar sashen ganye da sauri tana sa wurin ya koma ruwan kasa kamar takarda. Kamuwa mai tsanani yana sa ganye ya mutu gaba ɗaya ya faɗi, tsiro ya zama tsirara.",
            causes = "Galibi Phytophthora capsici a lokacin zafi sosai (28 zuwa 32 °C) da danshi. Botrytis cinerea (fulawar toka) ma na iya haifar da ita a lokacin sanyi da danshi, ko Colletotrichum capsici a wurin da danshi ya yi yawa.",
            effects = "Faɗuwar ganye da sauri tana bar 'ya'ya a fili ga rana da sauran cututtuka. Faɗuwar 'ya'ya kafin lokaci tana rage amfani sosai. Faɗuwar ganye akai-akai tana raunana tsiro sosai kuma tana iya sa ya mutu gaba ɗaya.",
            prevention = "Yi kunyoyi masu tsayi domin ruwa ya fita da kyau. Kada ka yi ban ruwa daga sama. Rage yawan tsire-tsire domin iska ta shiga. Kada ka taɓa tsiro lokacin da yake da danshi. Cire ka lalata abin da ya kamu da sauri.",
            organicMitigation = "• Fesa Bordeaux mixture a matsayin kariya duk kwana 10 zuwa 14.\n• Fesa potassium silicate a kan ganye domin ƙarfafa bangon ƙwayoyin ganye.\n• Cire ganyen da suka kamu da sharar tsire-tsire nan take.\n• Inganta fitar ruwa da kunyoyi masu tsayi da sa kayan halitta a ƙasa.\n• Fesa maganin Bacillus subtilis (misali Serenade) a kan ganye.",
            chemicalMitigation = "• Metalaxyl + Mancozeb: Ga cutar da Phytophthora yake haifarwa; sa a matsayin kariya.\n• Copper hydroxide + Mancozeb: Yana magance cututtuka da yawa; sa da zarar cutar ta bayyana.\n• Iprodione (Rovral 500SC): Yana da tasiri kan Botrytis; sa a lokacin sanyi da danshi.\n• Azoxystrobin: Yana shiga cikin tsiro; yana magance yawancin cututtukan ganye.\n• Haɗa maganin taɓawa da na shiga cikin tsiro a tanki domin aiki da sauri."
        ),

        12 to DiseaseTranslation(
            localName = "Mako Nhwiren Kurukuruwa (cutar naɗewar ganyen barkono)",
            description = "Cuta ce ta ƙwayar cuta wadda take sa ganye ya naɗe sosai, ya yi tsuma, kuma tsiro ya yi gajarta. Farin ƙwaro kaɗai yake ɗauka, kuma tana yaɗuwa da sauri a gonar barkono musamman a lokacin rani lokacin da farin ƙwaro ya yawaita. Babu magani; riga-kafi da magance ƙwaron su ne mabuɗi.",
            symptoms = "Ganye yana naɗewa sosai sama ko ƙasa kuma yana yin tsuma. Ganyen da ya naɗe yakan zama ƙarami da gefe rawaya. Tsire-tsire da suka kamu suna yin gajarta, ba sa yin fure sosai, kuma suna ba da 'ya'ya kaɗan ko babu. Tsiron gaba ɗaya yana kama da wanda ya lalace.",
            causes = "Chilli Leaf Curl Virus (ChiLCV) ko Tomato Leaf Curl Virus (TLCV) wanda farin ƙwaro (Bemisia tabaci) yake ɗauka. Ƙwayar cutar ba ta yaɗuwa ta ƙasa, ko kayan aiki, ko taɓawa — sai da ƙwaron.",
            effects = "Tsire-tsire da suka kamu ba sa ba da amfani — ana rasa amfani gaba ɗaya idan sun kamu tun suna ƙanana. Ƙwayar cutar tana yaɗuwa da sauri a gona yayin da farin ƙwaro yake motsi. Ana iya rasa amfani gaba ɗaya a lokacin barkewa, musamman a rani.",
            prevention = "Yi gandu a ƙarƙashin raga mai hana ƙwari domin samun tsire-tsire marasa cuta. Kiyaye wurin daga farin ƙwaro a cikin mako 3 zuwa 4 na farko bayan dasawa. Cire ka lalata tsire-tsire da suka kamu da wuri domin rage mafakar ƙwayar cutar. Kada ka shuka barkono kusa da tumatir, taba, ko sauran irinsu.",
            organicMitigation = "• Yi amfani da rufin ƙasa mai haske (azurfa ko aluminum): Yana rikitar da farin ƙwaro da hasken da yake nunawa.\n• Sa tarkon rawaya mai manne (30 a kowace hekta): Yana kama farin ƙwaro kuma yana nuna adadinsu.\n• Fesa man neem (kashi 3 zuwa 4) da sabulun ƙwari (kashi 0.5) kowane mako: Yana kashe ƙananan farin ƙwaro da ƙwansu.\n• Shuka marigold (Tagetes spp.) a gefen gona: Yana korar farin ƙwaro.\n• Cire ka lalata dukan tsire-tsire da suka kamu nan take domin rage mafakar ƙwayar cutar.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL): Zuba a ƙasa ko fesa a ganye; yana da tasiri sosai kan farin ƙwaro; sa da zarar ka gan su.\n• Thiamethoxam (Actara 25WG): Yana shiga cikin tsiro; zuba a ƙasa lokacin dasawa yana kare tsiro mako 4 zuwa 6.\n• Spiromesifen (Oberon): Yana da tasiri kan ƙananan farin ƙwaro da ƙwansu; ka canza tsakaninsa da neonicotinoids.\n• Pyriproxyfen (Admiral): Yana hana farin ƙwaro girma daidai.\n• Lura: Babu maganin da yake warkar da cutar ƙwayar cuta idan ta kama — dukan ƙoƙari ya kasance kan magance ƙwaron."
        ),

        13 to DiseaseTranslation(
            localName = "Mako Nhwiren Mfirimiri (cutar zanen ganyen barkono)",
            description = "Cuta ce ta ƙwayar cuta wadda take yin zane na kore mai haske, kore mai duhu da rawaya a ganye, tare da lalacewar ganye da gajarta. Ƙwarin aphid da taɓawa suke yaɗa ta, saboda haka tana yaɗuwa da sauri a gona da ake kula da ita.",
            symptoms = "Wurare masu sauyawa tsakanin kore mai haske, rawaya da kore mai duhu (zane) a saman ganye. Ganye na iya zama ƙunƙuntacce, mai tsuma, ko marar siffa. Sabbin harbe suna yin gajarta da lalacewa. Tsire-tsire suna ba da 'ya'ya ƙanana, galibi marasa kyau kuma marasa daraja.",
            causes = "Tobacco Mosaic Virus (TMV), Cucumber Mosaic Virus (CMV), ko Pepper Mosaic Virus (PepMV). TMV yana yaɗuwa ta taɓawa (hannu, kayan aiki) da kuma ta iri da suka kamu. CMV kuwa galibi ƙwarin aphid (Myzus persicae, Aphis gossypii) suke yaɗa shi.",
            effects = "Raguwar amfani kashi 30 zuwa 70 a tsire-tsire da suka kamu. Rashin ɗaukar 'ya'ya, 'ya'ya ƙanana marasa kyau da ƙarancin daraja a kasuwa. Babu warkarwa. Ƙwayoyin cuta da aphid yake ɗauka na iya kama gona duka da sauri idan aphid ya yawaita.",
            prevention = "Shuka nau'in barkono da yake jure wannan cuta (ana samu daga IITA da CSIR-SARI a Ghana). Magance aphid — su ne manyan masu yaɗawa. Wanke dukan kayan aiki da maganin bleach kashi 10 ko giya kashi 70 kafin da bayan aiki. Wanke hannu kafin taɓa tsiro. Kada ka sha taba kusa da tsiro (tushen TMV).",
            organicMitigation = "• Fesa man neem (kashi 2) kowane mako domin magance aphid — yana da tasiri kan manya da ƙanana.\n• Rufin ƙasa mai haske na azurfa: Yana hana aphid sauka.\n• Cire tsire-tsire da suka kamu nan take — sa a jaka, fitar da su daga gona, ka lalata su.\n• Fesa madara mara mai da aka narkar (kashi 1 na madara zuwa kashi 9 na ruwa) a kan kayan aiki da hannu — yana lalata TMV.\n• Shuka coriander, dill, ko fennel kusa domin jawo maƙiyan aphid (ladybird, lacewing).",
            chemicalMitigation = "• Imidacloprid (Confidor) ko Acetamiprid (Mospilan): Maganin ƙwari da yake shiga cikin tsiro domin magance aphid; sa da zarar ka ga aphid.\n• Malathion (Malathion 57 EC): Maganin taɓawa mai tasiri kan aphid; yi amfani da shi domin kashe su da sauri.\n• Man ma'adinai (horticultural oil): Yana rage ikon aphid na yaɗa CMV.\n• Pymetrozine (Chess WG): Maganin aphid da ba ya cutar da ƙwari masu amfani; yana tafiya da kyau tare da neonicotinoids.\n• Babu maganin da yake warkar da cutar ƙwayar cuta — dukan matakan su nemi hana kamuwa."
        ),

        14 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko Ketewa (cutar ƙananan tabo ta barkono)",
            description = "Cuta ce ta naman gwari wadda take yin ƙananan tabo masu yawa a ganyen barkono, wanda yake haifar da faɗuwar ganye a hankali. Naman gwarin yana bunƙasa a lokacin zafi da danshi. Ko da yake ba ta da tsanani kamar cutar mutuwar ganye, kamuwa akai-akai a cikin kaka yana rage amfani sosai.",
            symptoms = "Ƙananan tabo masu yawa masu zagaye (milimita 2 zuwa 5) da baki ruwan kasa mai duhu da tsakiya toka-fari. Ana ganin ƙananan baƙaƙen tsaki (pycnidia — inda naman gwari yake ba da ƙwayoyi) a tsakiya idan an yi amfani da gilashin ƙara girma. Ganyen da ya kamu yana yin rawaya ya faɗi kafin lokacinsa.",
            causes = "Naman gwari Septoria capsici. Yana rayuwa a cikin sharar tsire-tsire da ta kamu da kuma a ƙasa. Tsatsan ruwan sama da ban ruwa daga sama suna yaɗa ƙwayoyinsa. Zafi (20 zuwa 25 °C) da danshi mai yawa da ruwa a kan ganye suna taimaka wa kamuwa.",
            effects = "Faɗuwar ganye daga gindi zuwa sama tana rage yin abinci da amfanin 'ya'ya. Asara kashi 25 zuwa 50 na iya faruwa a gonar da ba a kula da ita a lokacin damina. Faɗuwar ganye akai-akai tana raunana tsiro tana rage tsawon lokacin da yake ba da amfani.",
            prevention = "Rufe gindin tsiro da kayan halitta masu kauri domin hana tsatsan ƙasa ya kai ga ganyen ƙasa. Kada ka yi ban ruwa daga sama — yi amfani da ban ruwa na ɗigo. Bar sarari fiye da santimita 60 domin iska ta shiga. Cire ka lalata sharar da ta kamu bayan girbi. Yi juyin shuka na shekara 2 zuwa 3.",
            organicMitigation = "• Rufe ƙasa sosai (ciyawa, ɓawon shinkafa) kewaye da tsiro domin hana tsatsan ƙasa ya yaɗa ƙwayoyin cutar.\n• Fesa maganin tagulla (Bordeaux mixture) a matsayin kariya duk kwana 10 zuwa 14.\n• Cire ganyen ƙasa da suka kamu da zarar ka gan su domin rage yaɗuwar cutar.\n• Fesa haɗin man neem da bicarbonate domin hana naman gwari girma.\n• Bar sarari mai kyau ka datse rassan ƙasa domin iska ta shiga.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Maganin kariya; sa duk kwana 7 zuwa 10 a lokacin danshi.\n• Chlorothalonil (Bravo 500): Maganin taɓawa mai tasiri; sa duk kwana 10 zuwa 14.\n• Tebuconazole (Folicur 250EW): Yana shiga cikin tsiro; yana kariya kuma yana warkarwa; sa da zarar cutar ta bayyana.\n• Azoxystrobin: Yana shiga cikin tsiro; yana da tasiri sosai; sa duk kwana 14.\n• Canza nau'in maganin duk sa 2 zuwa 3 domin kada cutar ta saba da shi."
        ),

        // ── TUMATIR ───────────────────────────────────────────────────────────

        15 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko (tabon ƙwayoyin cuta na tumatir)",
            description = "Cuta ce ta ƙwayoyin cuta mai yin barna, tana kama ganye, kara da 'ya'ya a lokacin zafi da danshi. Ta zama ruwan dare a yankunan noman tumatir na Ghana a damina. Tabo a kan 'ya'ya yana rage darajarsu a kasuwa da tsawon lokacin da suke ɗauka, wanda yake haifar da babbar asara.",
            symptoms = "Ƙananan tabo ruwan kasa mai duhu, masu zagaye ko marasa siffa (milimita 2 zuwa 5), da da'ira rawaya a kan ganye. Tabon na iya haɗuwa ya zama manyan wurare da suka mutu. Kara yana yin tabo duhu masu tashi da tsayi. Danyen 'ya'ya suna yin tabo ruwan kasa mai duhu masu tashi kamar ƙaiƙayi, waɗanda suke ci gaba har 'ya'yan sun nuna.",
            causes = "Ƙwayar cuta Xanthomonas perforans (nau'in T3/T4), X. vesicatoria, ko makamantansu. Tana yaɗuwa ta tsatsan ruwan sama, raɓa, ban ruwa daga sama, kayan aiki masu ɗauke da ita, da iri ko tsire-tsire da suka kamu. Kamuwa yana buƙatar ruwa a saman ganye na aƙalla minti 30.",
            effects = "Faɗuwar ganye mai tsanani tana bar 'ya'ya a fili ga rana. Tabo a kan 'ya'ya yana rage darajarsu a kasuwa kashi 50 zuwa 80. Asarar amfani na iya kai kashi 50 a shekarar barkewa. Ana ƙin tumatir na fitarwa waje saboda aibu. Tumatir da ya kamu ba ya ɗaukar lokaci bayan girbi.",
            prevention = "Yi amfani da iri da tsire-tsire da aka tabbatar ba su da cuta kaɗai. Kada ka yi ban ruwa daga sama — yi amfani da ban ruwa na ɗigo. Yi juyin shuka na shekara 3 da amfanin gona da ba na tumatir ba. Rage aiki a gona lokacin da tsiro yake da danshi. Wanke kayan aiki tsakanin layuka da maganin bleach kashi 10.",
            organicMitigation = "• Fesa Bordeaux mixture (copper sulfate kashi 1 + lemun ƙasa kashi 0.5) duk kwana 7 zuwa 10 a lokacin danshi.\n• Fesa haɗin man neem da sabulun castile a matsayin ƙarin kariya tsakanin fesa tagulla.\n• Rufe ƙasa sosai a gindin tsiro domin hana tsatsan ƙasa (tushen cutar).\n• Cire ka lalata ganye da sharar da suka kamu akai-akai.\n• Sa taki na ganye domin inganta rayuwar ƙasa da garkuwar tsiro.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000 ko Funguran OH): Sa duk kwana 7 zuwa 10; shi ne maganin da aka fi amfani da shi.\n• Copper oxychloride + Mancozeb (Cuprosan ko Curzate): Haɗi mai tasiri ga ƙwayoyin cuta da naman gwari.\n• Streptomycin sulfate (Agri-Mycin): Yi amfani da shi a canjawa tare da tagulla; kada ya wuce sa 2 zuwa 3 domin kada cutar ta saba da shi.\n• Kasugamycin (Kasumin): Madadin maganin ƙwayoyin cuta mai tasiri kan Xanthomonas.\n• Kada ka sa tagulla a lokacin zafi da rana mai ƙarfi domin gudun ƙona ganye."
        ),

        16 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ohow Ntem (cutar ƙona ganyen tumatir da wuri)",
            description = "Ɗaya daga cikin cututtukan naman gwari da suka fi yaɗuwa a tumatir a duniya, kuma ta zama ruwan dare sosai a Ghana. Zanen tabo kamar abin harbi a tsofaffin ganye na ƙasa shi ne alamarta. Kamuwa mai tsanani na iya sa ganye ya faɗi gaba ɗaya, ya rage amfani kashi 50 zuwa 80.",
            symptoms = "Tabo masu duhu (milimita 5 zuwa 15) da da'ira kamar abin harbi, da farko a tsofaffin ganye na ƙasa. Da'ira rawaya na iya kewaye tabon. Yayin da cutar take hawa, ganye yana yin rawaya ya faɗi kafin lokacinsa. Kara na iya yin tabo duhu masu tsayi da nutsewa (ruɓewar wuya a ƙananan tsire-tsire).",
            causes = "Naman gwari Alternaria solani (da A. alternata). Yana zaune a ƙasa da kuma a iri. Yana rayuwa a cikin sharar amfanin gona. Zafi (24 zuwa 29 °C), danshi mai yawa, da sauyawa tsakanin jiƙa da bushewa suna taimaka masa. Tsatsan ruwan sama da iska suna yaɗa ƙwayoyinsa.",
            effects = "Faɗuwar ganye tana hawa daga gindi zuwa sama, tana rage yin abinci sosai. Faɗuwar ganye mai tsanani tana bar 'ya'ya ga rana kuma tana rage yin zaƙi. Asara kashi 50 zuwa 80 na iya faruwa a kaka mai tsanani. Tsire-tsire da suka raunana suna kamuwa da sauran cututtuka.",
            prevention = "Datse ganyen ƙasa da suke taɓa ƙasa domin hana tsatsan ƙasa ya kai musu. Rufe gindin tsiro da ciyawa mai kauri. Bar sarari aƙalla santimita 60 tsakanin tsire-tsire. Yi wa tsiro sanda ko keji domin ganye kada ya taɓa ƙasa. Yi juyin shuka na shekara 3 da amfanin gona da ba na tumatir ba.",
            organicMitigation = "• Rufe ƙasa da ciyawa ko busasshiyar ciyawa (kauri santimita 8 zuwa 10) domin hana tsatsan ƙasa — ita ce babbar hanyar kamuwa.\n• Datse ganyen ƙasa da suka kamu nan take ka lalata su.\n• Fesa copper sulfate (Bordeaux mixture) duk kwana 10 a matsayin kariya.\n• Fesa man neem (kashi 2) ga ƙananan kamuwa na farko.\n• Fesa calcium a kan ganye (calcium nitrate ko calcium chloride kashi 0.5) domin ƙarfafa bangon ƙwayoyin ganye ya rage yaɗuwar cutar.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 ko Daconil): Shi ne aka fi amfani da shi; sa duk kwana 7 zuwa 10 a matsayin kariya.\n• Mancozeb (Dithane M-45): Maganin kariya mai tasiri; sa a canjawa tare da Chlorothalonil.\n• Azoxystrobin (Amistar): Yana shiga cikin tsiro; sa duk kwana 14; yana da kyau sosai a shirin gaba ɗaya.\n• Difenoconazole (Score 250EC): Maganin DMI; sa da zarar ka ga alamar cutar.\n• Boscalid + Pyraclostrobin (Signum): Haɗi mai inganci na SDHI da strobilurin domin kariya a duk kaka."
        ),

        17 to DiseaseTranslation(
            localName = "Ntomato Kobuo (cutar yaushewar tumatir)",
            description = "Cuta ce ta naman gwari da ke zaune a ƙasa, tana yin barna sosai. Tana toshe hanyoyin ruwa na tsiro, tana hana ruwa da abinci su kai sassan tsiron. Idan ƙasa ta kamu, cutar tana zama a can har abada. Babbar matsala ce ga noman tumatir a yankunan gandun daji na Ghana inda zafin ƙasa ya dace da ita.",
            symptoms = "Rawaya na ganye, galibi yana farawa daga gefe ɗaya na reshe ko tsiro. Yaushewar ganye a lokacin zafi na rana. Yaushewar ba ta warkewa da ban ruwa. Canjin launi ruwan kasa zuwa ja a hanyoyin ruwa na tsiro, ana ganinsa idan aka yanke kara kusa da gindi.",
            causes = "Naman gwari Fusarium oxysporum f. sp. lycopersici (nau'i 1, 2 da 3) da ke zaune a ƙasa. Yana rayuwa a ƙasa har abada a matsayin chlamydospores (fiye da shekara 20). Ƙasa mai zafi (25 zuwa 30 °C) da ƙasa mai tsami (pH ƙasa da 5.5) suna taimaka masa. Yana shiga ta saiwoyi ta rauni ko ramuka na halitta.",
            effects = "Mutuwar tsiro cikin kwanaki zuwa makonni bayan alamun sun bayyana. Ana iya rasa amfani gaba ɗaya a gonar da ta kamu sosai. Ƙasa tana ci gaba da ɗauke da cutar shekaru masu yawa — amfanin gona da za a shuka a wurin nan gaba yana cikin haɗari. Babu warkarwa. Wannan babban dalili ne da yake sa manoman tumatir su bar gonakinsu.",
            prevention = "Shuka nau'in da yake jure Fusarium kaɗai (nemi harafin F, FF ko FFF a kan leda — yana nuna juriya ga nau'i 1, 2 da 3). Kiyaye pH na ƙasa tsakanin 6.5 zuwa 7.0 ta sa lemun ƙasa. Inganta fitar ruwa daga ƙasa. Ka ɗauko tsire-tsire daga gonakin gandu masu inganci kaɗai. Kada ka sake shuka tumatir a ƙasa da ta kamu har shekara 5 zuwa 7.",
            organicMitigation = "• Ƙona ƙasa da rana: Jiƙa ƙasa sosai sannan ka rufe da leda mai haske na micron 50 na mako 4 zuwa 6 a lokacin zafi — yana rage Fusarium kashi 90 a santimita 15 na sama.\n• Trichoderma harzianum (misali Trichomax, Biomax-T): Haɗa a ramin dasawa ko zuba a ƙasa; yana gogayya da Fusarium ya lalata shi.\n• Naman gwari mai amfani (Glomus intraradices): Sa a saiwoyi lokacin dasawa; yana ƙara ɗaukar abinci da lafiyar saiwoyi.\n• Gyaɗar neem: Haɗa gram 200 ga kowane tsiro a ramin dasawa.\n• Sa taki na ganye: Yana inganta rayuwar ƙasa wadda take hana Fusarium.",
            chemicalMitigation = "• Carbendazim (Bavistin 50WP): Zuba a ƙasa lokacin dasawa a matsayin kariya kaɗai.\n• Metalaxyl + Thiram: Maganin iri domin kare saiwoyin ƙananan tsire-tsire lokacin tsirowa.\n• Fludioxonil (Maxim): Maganin iri mai tasiri sosai kan ruɓewar gindi da saiwa da Fusarium yake haifarwa.\n• Metam sodium (maganin ƙasa): Ana amfani da shi a yanayi mai tsanani kafin shuka — yana buƙatar ƙwararre.\n• Muhimmi: Babu maganin da yake warkar da wannan cuta idan ta riga ta shiga hanyoyin ruwa na tsiro."
        ),

        18 to DiseaseTranslation(
            localName = "Ntomato Pa (tumatir mai lafiya)",
            description = "Wannan tsiron tumatir yana da cikakkiyar lafiya, yana girma sosai kuma yana da ikon ba da amfani mai yawa. Tumatir mai lafiya da ake kula da shi sosai yana ba da 'ya'ya masu yawa da inganci, wanda yake taimaka wa ribar manomi da abinci a Ghana.",
            symptoms = "Ganye kore mai duhu iri ɗaya, babu tabo, babu layuka, babu rawaya ko yaushewa. Kara mai ƙarfi da yake ɗaukar nauyin tsiro. Furanni rawaya masu siffar tauraro. Danyen 'ya'ya lallausa masu launi iri ɗaya, suna juyawa ja yadda ya kamata idan sun nuna.",
            causes = "pH na ƙasa da ya dace (6.0 zuwa 6.8), shayarwa akai-akai daidai (milimita 25 zuwa 40 a mako), taki NPK mai daidaito da ƙananan abinci, isasshen sarari, da kula da ƙwari da cututtuka akai-akai.",
            effects = "Amfani mai yawa, 'ya'ya masu girma, ɗanɗano mai kyau, launi mai kyau da tsawon lokacin ajiya. Tsire-tsire masu ƙarfi suna jure matsalolin da suka saba faruwa. Samarwa akai-akai yana ba da riba ga manomi da abinci a gida.",
            prevention = "Ci gaba da yadda kake kula da gonar. Duba tsire-tsire sau biyu a mako domin ganin alamun cuta ko ƙwari da wuri. Kula da sanduna ko keji yayin da tsiro yake girma. Datse harben da ba sa ba da 'ya'ya domin ƙarfin ya koma ga 'ya'ya. Ajiye rikodin shuka, abin da ka sa, da amfanin da ka samu.",
            organicMitigation = "• Sa kayan halitta da suka ruɓe sosai (kilo 3 zuwa 5 ga kowane tsiro) lokacin shuka.\n• Rufe ƙasa da ciyawa (kauri santimita 10) domin riƙe danshi da hana ciyawa.\n• Yi wa tsiro sandan bamboo ko keji na waya domin gudun karyewar kara da inganta shigar iska.\n• Shuka basil (yana korar thrips da aphid) da marigold (yana korar tsutsotsi da farin ƙwaro) kusa da tumatir.\n• Fesa ruwan tsire-tsire da aka bar su su yi tsami ko ruwan taki a kan ganye domin ƙarfafa garkuwar tsiro.",
            chemicalMitigation = "• Sa NPK 15-15-15 lokacin shuka, sannan ka koma taki mai ƙarancin nitrogen (misali 8-24-24) a lokacin 'ya'ya.\n• Fesa calcium nitrate (kashi 0.5) a kan ganye lokacin fure domin hana ruɓewar gindin 'ya'ya.\n• Fesa tagulla (Bordeaux mixture) a matsayin kariya a farkon damina.\n• Shirin maganin ƙwari na kariya ga farin ƙwaro da aphid (yi wa iri maganin Imidacloprid a matakin gandu).\n• Sa potassium sulfate a lokacin da 'ya'ya suke girma domin inganta ingancinsu da juriyarsu ga cututtuka."
        ),

        19 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kwanee (cutar mutuwar ganyen tumatir)",
            description = "Cutar tumatir da aka fi ji tsoro a duniya — irin cutar da ta haifar da yunwar dankalin Ireland a shekarun 1840. Tana iya lalata gonar tumatir duka cikin kwana 7 zuwa 10 a lokacin sanyi da danshi. Tana yin barna sosai a damina a Ghana. Yin gaggawa da zarar an gan ta yana da matuƙar muhimmanci.",
            symptoms = "Manyan tabo (santimita 2 zuwa 3) masu duhu, toka-ruwan kasa, kamar an shafa musu mai, a ganye da kara. A lokacin danshi mai yawa, farin fulawa mai laushi tana fitowa a ƙarƙashin ganye. Tabo ruwan kasa mai duhu kuma mai ƙarfi a kan 'ya'ya. Kara da ya kamu yana faɗuwa. Gona duka na iya kama da wadda wuta ta ci cikin kwanaki.",
            causes = "Phytophthora infestans. Iska tana ɗaukar ƙwayoyinsa fiye da kilomita 50. Sanyi da dare (10 zuwa 20 °C) da danshi mai yawa su ne mafi dacewa da kamuwa. Tsiro ɗaya da ya kamu ko gonar dankali da ta kamu kusa da nan na iya fara barkewa.",
            effects = "Lalata amfani gaba ɗaya cikin kwana 7 zuwa 10 idan yanayi ya dace da cutar. Kamuwar 'ya'ya tana sa ba a iya sayar da amfanin gona duka. Babbar asara — barkewa ɗaya na iya lalata al'ummar manoma duka. Tana daga cikin cututtukan tsire-tsire da suka fi yin barna a duniya.",
            prevention = "Shuka nau'in da yake jure cutar (misali Ferline, Legend, Defiant) idan akwai su. Bi hasashen yanayi — dare mai sanyi da danshi mai yawa suna nufin haɗari mai girma. Sa magani kafin alamun farko su bayyana a lokacin haɗari. Kiyaye gona ta bushe — kada ka yi ban ruwa daga sama. Duba gona kowace rana a lokacin sanyi da ruwan sama.",
            organicMitigation = "• Bordeaux mixture (copper sulfate kashi 3 zuwa 4 + lemun ƙasa kashi 3): Fesa duk kwana 5 zuwa 7 a lokacin sanyi da danshi — wannan shi ne babban maganin kariya na halitta.\n• Cire ka lalata DUKAN tsiron da ya kamu nan take — sa a jaka, fitar da su daga gona, kada ka mai da su taki.\n• Inganta fitar ruwa daga gona kuma kada ka shuka a wuraren kwari.\n• Copper octanoate (Cueva): Maganin tagulla da aka yarda da shi ga noma na halitta; sa duk kwana 5 a lokacin haɗari.\n• Kada ka yi ban ruwa daga sama a lokacin sanyi — yi amfani da ban ruwa na ɗigo kaɗai.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ 68WG): Maganin farko; sa duk kwana 7 a matsayin kariya a lokacin sanyi da danshi — kada ka jira alamun cutar.\n• Cymoxanil + Famoxadone (Equation Pro): Haɗin da yake shiga cikin tsiro kuma yake kariya; sa duk kwana 5 zuwa 7.\n• Dimethomorph (Forum): Yana shiga cikin tsiro; yana da tasiri bayan kamuwa da wuri; ka canza tsakaninsa da Ridomil.\n• Fluopicolide + Propamocarb (Infinito): Yana shiga cikin tsiro sosai; sa duk kwana 7 zuwa 10.\n• Canza dukan nau'in magani duk sa 2 domin Phytophthora yana saba da magani da sauri sosai."
        ),

        20 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kurukuruwa (cutar naɗewar ganyen tumatir)",
            description = "Ana kuma kiranta cutar naɗewar ganye rawaya ta tumatir (TYLCV). Wannan ƙwayar cuta da farin ƙwaro yake ɗauka tana daga cikin cututtukan tumatir da suka fi yin barna a duniya. Farin ƙwaro Bemisia tabaci kaɗai yake ɗauka. Tana yin barna sosai a rani a Ghana lokacin da farin ƙwaro ya yawaita.",
            symptoms = "Ganye yana naɗewa sosai sama da ciki, gefensa yana yin rawaya. Ganyen da ya kamu yakan zama ƙarami, mai kauri kuma mai tauri. Gajartar sassan kara tana sa tsiro ya zama kamar kurmi mai kanƙanta. Gajarta mai tsanani — tsiro ba ya wuce santimita 30. Ba sa ɗaukar 'ya'ya; idan sun ɗauka, ƙanana ne kuma launinsu ba shi da kyau.",
            causes = "Tomato Yellow Leaf Curl Virus (TYLCV), ƙwayar cuta ta Begomovirus da Bemisia tabaci kaɗai yake ɗauka. Farin ƙwaro guda ɗaya mai ɗauke da ƙwayar cutar na iya kama tsiro cikin mintuna kaɗan na cizo. Babu wata hanyar yaɗuwa — ba ta ƙasa ko kayan aiki ba.",
            effects = "Rasa amfani gaba ɗaya idan tsire-tsire sun kamu a cikin mako 3 zuwa 4 na farko bayan dasawa. Waɗanda suka kamu daga baya na iya ba da kashi 20 zuwa 30 na amfanin da ake tsammani. Ƙwayar cutar tana yaɗuwa da sauri — tarin farin ƙwaro ɗaya na iya kama gona duka cikin mako 2. Babbar asara musamman a noman tumatir na rani.",
            prevention = "Yi gandu a ƙarƙashin raga mai kyau (mesh 50) domin samun tsire-tsire marasa farin ƙwaro. Yi sabuwar gona nesa da gonakin tumatir da suka kamu. Cire ka lalata dukan tumatir da ya tsiro da kansa, domin shi ne mafakar ƙwayar cutar. Bi adadin farin ƙwaro da tarkon rawaya mai manne tun daga dasawa.",
            organicMitigation = "• Raga mai kyau mai hana ƙwari (mesh 50) a kan gadon iri: yana hana farin ƙwaro isa ga ƙananan tsire-tsire a lokacin girma mai muhimmanci.\n• Rufin ƙasa mai haske na azurfa ko aluminum: Yana korar farin ƙwaro; yana da tasiri sosai a farkon kaka.\n• Tarkon rawaya mai manne (20 zuwa 30 a kowace hekta): Yana kama farin ƙwaro kuma yana nuna adadinsu.\n• Fesa man neem (kashi 3 zuwa 4) da sabulun ƙwari kowane mako: Yana magance ƙananan farin ƙwaro da ƙwansu.\n• Cire ka lalata dukan tsire-tsire da suka kamu nan take — su ne tushen ƙwayar cutar ga gona duka.",
            chemicalMitigation = "• Zuba Imidacloprid (Confidor 200SL) a ƙasa lokacin dasawa: Yana kare tsiro mako 4 zuwa 6 — ita ce hanya mafi tasiri ta kariya da wuri.\n• Thiamethoxam (Actara 25WG) a matsayin maganin iri ko zuba a ƙasa: Yana magance farin ƙwaro sosai.\n• Spiromesifen (Oberon): Yana kai wa ƙwan farin ƙwaro da ƙanana; ka canza tsakaninsa da neonicotinoids domin kada su saba da shi.\n• Buprofezin (Applaud): Yana hana farin ƙwaro sauya fata; a yi amfani da shi a canjawa.\n• Muhimmi: Babu maganin ƙwayar cuta — dukan ƙoƙari ya kai ga farin ƙwaro kafin ya yaɗa cutar."
        ),

        21 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Mfirimiri (cutar zanen ganyen tumatir)",
            description = "Ƙwayar cuta ce mai ƙarfi wadda take yaɗuwa ta taɓawa, tana haifar da zane da kumburi a ganyen tumatir. Tobacco Mosaic Virus (TMV) tana daga cikin cututtukan tsire-tsire da aka fi bincika — tana da ƙarfi sosai kuma tana iya ci gaba da kamuwa a busasshiyar taba shekaru masu yawa. Kayan aiki da hannu masu ɗauke da ita su ne manyan hanyoyin yaɗuwa.",
            symptoms = "Wurare masu sauyawa tsakanin kore mai haske da kore mai duhu a ganye (zane). Ganye na iya lalacewa, ya zama ƙunƙuntacce ko kamar zare. Saman ganye na iya zama mai kumburi. Layuka ruwan kasa ko duhu masu nutsewa a kara. 'Ya'ya na iya nuna zane rawaya ko ruwan kasa a ciki.",
            causes = "Tobacco Mosaic Virus (TMV) ko Tomato Mosaic Virus (ToMV). Galibi tana yaɗuwa ta taɓawa: hannu, kayan aiki, tufafi, da ƙwari masu tsotsa. TMV tana da ƙarfi sosai — tana rayuwa a busasshiyar taba, a ƙasa, da a kan kayan aiki har watanni zuwa shekaru. Iri da suka kamu na iya yaɗa ta.",
            effects = "Raguwar amfani kashi 10 zuwa 35 saboda rashin ɗaukar 'ya'ya da samun 'ya'ya ƙanana marasa inganci. Ba a iya sayar da 'ya'ya masu zane. TMV tana daɗewa sosai — gona na iya ci gaba da kamuwa shekaru. Babu tsiron da ya kamu da yake warkewa. Tana yaɗuwa da sauri inda aka shuka da kusanci.",
            prevention = "Shuka nau'in da yake jure ƙwayar cutar kaɗai (kwayar halittar Tm-2 — tana cikin yawancin nau'in tumatir na zamani). Wanke dukan kayan aiki da maganin bleach kashi 10 ko giya kashi 70 kafin amfani da su da tsakanin tsire-tsire. Wanke hannu sosai da sabulu kafin taɓa tsiro. Kada ka sha taba ko ka taɓa taba kusa da tumatir (tushen TMV). Cire tsire-tsire da suka kamu da sauri.",
            organicMitigation = "• Shuka nau'in da yake jure TMV/ToMV (kwayar halittar Tm-2 ko Tm-2²) — ita ce kariya mafi inganci ita kaɗai.\n• Fesa madara mara mai (kashi 1 zuwa 10 da ruwa): Yana lalata sunadaran ƙwayar cutar a kan tsiro da kayan aiki; fesa a kan kayan aiki da hannu kafin aiki.\n• Cire ka lalata tsire-tsire da suka kamu nan take — kada ka mai da su taki; sa a jaka ka ƙone.\n• Yi wa iri magani da ruwan zafi (50 °C na minti 30) domin kawar da ƙwayar cutar kafin shuka.\n• Kada ka sa nitrogen da yawa, domin yana sa tsiro ya yi laushi ya kamu da sauri.",
            chemicalMitigation = "• Babu maganin da yake warkar da cutar ƙwayar cuta a tsire-tsire.\n• Imidacloprid ko Acetamiprid: Suna magance ƙwari masu tsotsa (aphid, thrips) da za su iya kai ƙwayar cutar ga tsiro lokacin cin abinci.\n• Maganin tayar da garkuwar tsiro (Acibenzolar-S-methyl / Actigard): Yana tayar da juriyar tsiro; yana iya rage tsananin alamun a wasu lokuta.\n• Man ma'adinai (horticultural oil): Idan aka fesa a ganye, yana iya rage yaɗuwar cutar ta taɓawa.\n• Dukan aikin ya dogara ne kan tsafta, nau'in da yake jure cutar, da cire tsiron da ya kamu."
        ),

        22 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko Ketewa (cutar ƙananan tabo ta tumatir)",
            description = "Ɗaya daga cikin cututtukan naman gwari da suka fi yawa a tumatir, tana yin tabo masu yawa da faɗuwar ganye a hankali daga gindi zuwa sama. Ta yaɗu sosai a damina a Ghana. Ko da yake ba kasafai take kashe tsiro ba, faɗuwar ganye akai-akai tana rage amfani da ingancin 'ya'ya sosai.",
            symptoms = "Ƙananan tabo masu yawa masu zagaye (milimita 2 zuwa 5) da baki ruwan kasa mai duhu da tsakiya fari zuwa toka. Ana ganin ƙananan baƙaƙen tsaki (pycnidia — inda ƙwayoyin naman gwari suke) a tsakiyar tabon idan an ƙara girmansa. Ganyen da ya kamu yana yin rawaya ya faɗi. Cutar tana hawa daga ganyen ƙasa zuwa sama.",
            causes = "Naman gwari Septoria lycopersici. Yana zaune a ƙasa kuma yana rayuwa a cikin sharar da ta kamu. Yana yaɗuwa ta tsatsan ruwan sama, ban ruwa daga sama, da taɓa tsiron da ya kamu. Zafi (20 zuwa 25 °C) da dogon lokacin danshi a ganye suna taimaka masa.",
            effects = "Faɗuwar ganye daga gindi zuwa sama tana rage yin abinci tana kuma bar 'ya'ya ga rana. Asara kashi 30 zuwa 60 ta zama ruwan dare a gonar da ba a kula da ita a lokacin danshi. Faɗuwar ganye akai-akai tana raunana tsiro tana rage jimillar amfanin kaka. Ingancin 'ya'yan da suka rage yana lalacewa saboda rana.",
            prevention = "Rufe gindin tsiro da kayan halitta masu kauri (santimita 5 zuwa 8) domin hana ruwan sama ya tsatsa ƙasa (babban tushen ƙwayoyin cutar) ya kai ga ganyen ƙasa. Datse ganyen ƙasa bayan tsiro ya girma. Yi amfani da ban ruwa na ɗigo — kada ka jiƙa ganye. Bar sarari fiye da santimita 60 domin iska ta shiga. Yi juyin shuka na shekara 3 da amfanin gona da ba na tumatir ba.",
            organicMitigation = "• Rufe ƙasa sosai kewaye da tsiro (ciyawa, ɓawon shinkafa, busasshiyar ciyawa): Yana hana tsatsan ƙasa, wanda shi ne babban tushen kamuwa.\n• Datse ganyen ƙasa da suka kamu da sauri ka fitar da su daga gona.\n• Fesa copper sulfate (Bordeaux mixture) duk kwana 10 zuwa 14 a matsayin kariya a lokacin danshi.\n• Fesa haɗin bicarbonate da man neem (cokali babba 1 na man neem + cokali ƙarami 1 na baking soda a kowace lita): Yana canza yanayin saman ganye ya hana ƙwayoyin naman gwari tsirowa.\n• Fesa ruwan taki a kan ganye: Ƙananan halittu masu amfani suna gogayya da Septoria su hana shi.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 ko Daconil 2787): Shi ne aka fi amfani da shi; sa duk kwana 7 zuwa 10 a matsayin kariya.\n• Mancozeb (Dithane M-45): Maganin kariya mai tasiri; sa a canjawa tare da Chlorothalonil.\n• Azoxystrobin (Amistar ko Quadris): Yana shiga cikin tsiro; yana da tasiri sosai; sa duk kwana 14.\n• Propiconazole (Tilt 250EC): Maganin DMI da yake shiga cikin tsiro; sa a farkon cutar domin warkarwa.\n• Trifloxystrobin + Tebuconazole (Nativo 75WG): Haɗi mai inganci; yana magance Septoria sosai a duk kaka."
        )
    )
}
